def create_solution_output(latex):

    result = step_by_step_solution(latex)

    output = {
        "input_latex": latex,
        "expression_type": result["type"],
        "steps": [],
        "final_answer": result["answer"]
    }

    for i, step in enumerate(result["steps"], 1):
        output["steps"].append({
            "step_number": i,
            "explanation": step
        })
    return output

